using Common.Utilities;
using Data.Contracts;
using Data.Contracts.Actions;
using Data.SystemAuth;
using Entities.App.Edms;
using Entities.App.Edms.Enums;
using Microsoft.EntityFrameworkCore;

namespace WebApp.Actions.Edms
{
	public class TransmitalAction(IUnitOfWork unitOfWork, ISdk sdk)
	{
		public const string CreatedFromTransmittalComment = "ایجاد شده از ترانسمیتال";

		private static readonly HashSet<string> SystemNotReviewComments = new(StringComparer.OrdinalIgnoreCase)
		{
			CreatedFromTransmittalComment,
			"Added by system",
			"created by system",
			"Auto generated by system administrator",
			"auto generated by system",
			"By System"
		};

		[EntityAction(typeof(Transmital), EntityActionTrigger.BeforeDelete, "RevertDocumentToApprovedByDcc", "بازگشت وضعیت مدرک به تایید DCC پس از حذف ترانسمیتال", Priority = 1)]
		public async Task RevertDocumentToApprovedByDcc(Transmital transmital, CancellationToken ct)
		{
			if (transmital.DocumentId is not > 0)
				return;

			var hasOtherTransmittal = await unitOfWork.Repository<Transmital>().TableNoTracking
				.AnyAsync(t => t.DocumentId == transmital.DocumentId && t.Id != transmital.Id, ct);
			if (hasOtherTransmittal)
				return;

			var document = await unitOfWork.Repository<Document>().Table
				.FirstOrDefaultAsync(d => d.Id == transmital.DocumentId, ct);
			if (document == null || document.Status != DocumentStatusEnums.NotReview)
				return;

			var latestComments = await unitOfWork.Repository<DocumentComment>().Table
				.Where(c => c.DocumentId == transmital.DocumentId)
				.OrderByDescending(c => c.Id)
				.Take(2)
				.ToListAsync(ct);

			var latest = latestComments.FirstOrDefault();
			var previousStatus = latestComments.Skip(1).FirstOrDefault()?.Status;
			var removedLatest = latest != null && IsSystemNotReviewComment(latest);

			if (removedLatest)
				await unitOfWork.Repository<DocumentComment>().DeleteAsync(latest!, ct, false);

			// ترانسمیتال معمولی باید دوباره Approved by DCC شود تا در فرم ترانسمیتال قابل انتخاب باشد.
			// Reply Sheet به وضعیت کامنت قبلی برمی‌گردد.
			document.Status = transmital.IsForReplySheet == true
				? (removedLatest ? previousStatus ?? DocumentStatusEnums.ApprovedByDcc : DocumentStatusEnums.NotReview)
				: DocumentStatusEnums.ApprovedByDcc;

			var now = DateTime.Now;
			document.ModifiedDateMiladiDateTime = now;
			document.ModifiedDateShamsiDateTime = now.ToShamsiDateTime();

			var user = sdk.CurrentUser;
			if (user != null)
			{
				document.ModifiedById = user.Id;
				document.ModifiedByName = user.FullName;
			}
		}

		private static bool IsSystemNotReviewComment(DocumentComment comment)
		{
			if (comment.Status != DocumentStatusEnums.NotReview)
				return false;

			var text = comment.Comment?.Trim();
			return string.IsNullOrEmpty(text) || SystemNotReviewComments.Contains(text);
		}
	}
}
